      navPillRect: navPill ? navPill.getBoundingClientRect() : null
    };

    // 3. Poster Cards Geometry
    const posterMedias = Array.from(document.querySelectorAll('.poster-media')).map(el => {
      const r = el.getBoundingClientRect();
      return {
        width: r.width,
        height: r.height,
        ratio: r.width / r.height,
        invRatio: r.height / r.width
      };
    });
    report.posterMediasSample = posterMedias.slice(0, 5);
    report.posterMediasTotal = posterMedias.length;

    // 4. Episode Cards Geometry
    const epMedias = Array.from(document.querySelectorAll('.episode-media')).map(el => {
      const r = el.getBoundingClientRect();
      return {
        width: r.width,
        height: r.height,
        ratio: r.width / r.height
      };
    });
    report.epMediasSample = epMedias.slice(0, 5);
    report.epMediasTotal = epMedias.length;

    // 5. Grid columns check in Movies view
    window.location.hash = '#movies';
    const moviesView = document.getElementById('view-movies');
    if (moviesView) {
      moviesView.classList.add('active');
    }
    const grid = document.querySelector('#view-movies .content-grid-6col');
    if (grid) {
      const cards = Array.from(grid.querySelectorAll('.card-poster'));
      report.moviesGrid = {
        gridRect: grid.getBoundingClientRect(),
        cardCount: cards.length,
        col1Card: cards[0] ? cards[0].getBoundingClientRect() : null,
        col6Card: cards[5] ? cards[5].getBoundingClientRect() : null
      };
    }

    // 6. Shelves check in Home view
    const shelf = document.querySelector('#view-home .content-shelf');
    const rail = document.querySelector('#view-home .shelf-rail');
    if (shelf && rail) {
      const railCards = Array.from(rail.querySelectorAll('.card-poster'));
      report.homeShelf = {
        shelfRect: shelf.getBoundingClientRect(),
        railRect: rail.getBoundingClientRect(),
        firstCardRect: railCards[0] ? railCards[0].getBoundingClientRect() : null,
        railScrollWidth: rail.scrollWidth,
        railClientWidth: rail.clientWidth
      };
    }

    // 7. Horizontal Scroll Attempt
    window.scrollTo(500, 0);
    document.body.scrollLeft = 500;
    document.getElementById('app').scrollLeft = 500;
    report.scrollLeftAfterAttempt = {
      windowScrollX: window.scrollX,
      bodyScrollLeft: document.body.scrollLeft,
      appScrollLeft: document.getElementById('app').scrollLeft
    };

    return JSON.stringify(report, null, 2);
  })()\`;

  const evalRes = await send('Runtime.evaluate', { expression: code, returnByValue: true });
  console.log('PROBE RESULTS:\n', evalRes.result.value);

  ws.close();
  chrome.kill();
}

probe().catch(console.error);
