/**
 * tests/adversarial-m2-layout.js
 * 
 * Empirical Adversarial Test Harness for Milestone 2:
 * Layout Boundaries, 1920x1080 Canvas Lock, Absence of Horizontal Page Scroll,
 * 5% TV-Safe Padding Adherence (96px/54px), and 2:3 Card Geometry.
 * 
 * Executes inside real Headless Chromium using the Chrome DevTools Protocol (CDP).
 */

const { spawn } = require('child_process');
const http = require('http');
const path = require('path');
const fs = require('fs');

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalTests = 0;
let passedTests = 0;
let failedTests = 0;
const failureDetails = [];

function assert(condition, message, details = {}) {
  totalTests++;
  if (!condition) {
    failedTests++;
    failureDetails.push({ message, details });
    console.log(`  ${C.red}✗ FAIL:${C.reset} ${message}`);
    if (Object.keys(details).length > 0) {
      console.log(`    ${C.gray}Details: ${JSON.stringify(details)}${C.reset}`);
    }
  } else {
    passedTests++;
    console.log(`  ${C.green}✓ PASS:${C.reset} ${message}`);
  }
}

async function runAdversarialLayoutTests() {
  console.log(`\n${C.bold}${C.cyan}===============================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}   Cinejoy webOS - M2 Layout Boundaries & Geometry Stress Suite ${C.reset}`);
  console.log(`${C.bold}${C.cyan}===============================================================${C.reset}\n`);

  const appHtmlPath = path.resolve(__dirname, '../app/index.html');
  const appFileUrl = `file://${appHtmlPath}`;
  const cdpPort = 9342;
  const userDataDir = `/tmp/chrome-m2-adversarial-${Date.now()}`;

  console.log(`${C.yellow}Launching Headless Chromium on port ${cdpPort}...${C.reset}`);

  const chrome = spawn('google-chrome-stable', [
    '--headless=new',
    `--remote-debugging-port=${cdpPort}`,
    `--user-data-dir=${userDataDir}`,
    '--no-sandbox',
    '--disable-gpu',
    '--window-size=1920,1080',
    '--force-device-scale-factor=1',
    appFileUrl
  ]);

  // Cleanup on exit
  const cleanup = () => {
    try { chrome.kill('SIGKILL'); } catch (e) {}
    try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch (e) {}
  };
  process.on('exit', cleanup);
  process.on('SIGINT', () => { cleanup(); process.exit(1); });

  // Wait for Chrome CDP readiness
  let listRes = null;
  for (let attempt = 0; attempt < 20; attempt++) {
    await new Promise(r => setTimeout(r, 200));
    try {
      listRes = await new Promise((resolve, reject) => {
        http.get(`http://127.0.0.1:${cdpPort}/json/list`, (res) => {
          let data = '';
          res.on('data', chunk => data += chunk);
          res.on('end', () => {
            try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
          });
        }).on('error', reject);
      });
      if (listRes && listRes.length > 0) break;
    } catch (e) {
      // retry
    }
  }

  if (!listRes) {
    throw new Error('Failed to connect to Headless Chromium CDP within timeout');
  }

  const pageTarget = listRes.find(t => t.url.includes('cinejoy-webos')) || listRes[0];
  console.log(`${C.green}Connected to CDP page target: ${pageTarget.title} (${pageTarget.url})${C.reset}\n`);

  const ws = new WebSocket(pageTarget.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);

  let msgId = 1;
  function sendCdp(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = msgId++;
      const handler = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.id === id) {
            ws.removeEventListener('message', handler);
            if (data.error) reject(new Error(data.error.message));
            else resolve(data.result);
          }
        } catch (err) {
          reject(err);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async function evaluate(code) {
    const res = await sendCdp('Runtime.evaluate', {
      expression: code,
      returnByValue: true,
      awaitPromise: true
    });
    return res.result.value;
  }

  // 1. Lock exact 1080p metrics
  await sendCdp('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false
  });

  // Give DOM scripts time to complete initialization
  await new Promise(r => setTimeout(r, 400));

  // =========================================================================
  // SUITE 1: 1920x1080 Canvas Lock & Container Bounding Verification
  // =========================================================================
  console.log(`${C.bold}${C.magenta}--- Suite 1: 1920x1080 Canvas Lock & Dimensions ---${C.reset}`);

  const canvasMetrics = await evaluate(`(() => {
    const html = document.documentElement;
    const body = document.body;
    const app = document.getElementById('app');
    const viewsContainer = document.querySelector('.views-container');
    const allViews = Array.from(document.querySelectorAll('.view')).map(v => ({
      id: v.id,
      width: v.offsetWidth,
      height: v.offsetHeight,
      rect: { left: v.getBoundingClientRect().left, top: v.getBoundingClientRect().top, width: v.getBoundingClientRect().width, height: v.getBoundingClientRect().height }
    }));

    const computedHtml = window.getComputedStyle(html);
    const computedBody = window.getComputedStyle(body);
    const computedApp = window.getComputedStyle(app);

    return {
      window: { width: window.innerWidth, height: window.innerHeight },
      html: {
        width: computedHtml.width,
        height: computedHtml.height,
        minWidth: computedHtml.minWidth,
        minHeight: computedHtml.minHeight,
        maxWidth: computedHtml.maxWidth,
        maxHeight: computedHtml.maxHeight,
        overflow: computedHtml.overflow
      },
      body: {
        width: computedBody.width,
        height: computedBody.height,
        minWidth: computedBody.minWidth,
        minHeight: computedBody.minHeight,
        maxWidth: computedBody.maxWidth,
        maxHeight: computedBody.maxHeight,
        overflow: computedBody.overflow,
        offsetWidth: body.offsetWidth,
        offsetHeight: body.offsetHeight
      },
      app: {
        width: computedApp.width,
        height: computedApp.height,
        offsetWidth: app.offsetWidth,
        offsetHeight: app.offsetHeight
      },
      viewsContainer: {
        width: viewsContainer.offsetWidth,
        height: viewsContainer.offsetHeight
      },
      views: allViews
    };
  })()`);

  assert(canvasMetrics.window.width === 1920, `Window innerWidth is locked to 1920px (observed: ${canvasMetrics.window.width})`);
  assert(canvasMetrics.window.height === 1080, `Window innerHeight is locked to 1080px (observed: ${canvasMetrics.window.height})`);
  assert(canvasMetrics.body.width === '1920px', `Body width is explicitly 1920px (observed: ${canvasMetrics.body.width})`);
  assert(canvasMetrics.body.height === '1080px', `Body height is explicitly 1080px (observed: ${canvasMetrics.body.height})`);
  assert(canvasMetrics.body.minWidth === '1920px' && canvasMetrics.body.maxWidth === '1920px', `Body width is clamped [min=1920px, max=1920px]`);
  assert(canvasMetrics.body.minHeight === '1080px' && canvasMetrics.body.maxHeight === '1080px', `Body height is clamped [min=1080px, max=1080px]`);
  assert(canvasMetrics.app.offsetWidth === 1920 && canvasMetrics.app.offsetHeight === 1080, `App root container is strictly 1920x1080 (observed: ${canvasMetrics.app.offsetWidth}x${canvasMetrics.app.offsetHeight})`);
  assert(canvasMetrics.viewsContainer.width === 1920 && canvasMetrics.viewsContainer.height === 1080, `Views container is strictly 1920x1080 (observed: ${canvasMetrics.viewsContainer.width}x${canvasMetrics.viewsContainer.height})`);
  assert(canvasMetrics.views.length === 6, `All 6 required views exist in DOM (found: ${canvasMetrics.views.length})`);
  for (const v of canvasMetrics.views) {
    assert(v.width === 1920 && v.height === 1080, `View container #${v.id} dimensions match 1920x1080 canvas lock (observed: ${v.width}x${v.height})`);
  }

  // Adversarial Viewport Stress: Resize viewport to non-standard resolutions
  console.log(`\n${C.yellow}  Testing canvas lock under non-standard viewport resizing stress...${C.reset}`);
  const testResolutions = [
    { w: 1280, h: 720 },
    { w: 2560, h: 1440 },
    { w: 3840, h: 2160 },
    { w: 1920, h: 1200 }
  ];

  for (const res of testResolutions) {
    await sendCdp('Emulation.setDeviceMetricsOverride', {
      width: res.w,
      height: res.h,
      deviceScaleFactor: 1,
      mobile: false
    });
    const resMetrics = await evaluate(`(() => {
      const app = document.getElementById('app');
      return {
        appWidth: app.offsetWidth,
        appHeight: app.offsetHeight
      };
    })()`);
    assert(resMetrics.appWidth === 1920 && resMetrics.appHeight === 1080,
      `App canvas dimensions remain locked to 1920x1080 when viewport resized to ${res.w}x${res.h} (observed: ${resMetrics.appWidth}x${resMetrics.appHeight})`);
  }

  // Restore 1920x1080
  await sendCdp('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false
  });

  // =========================================================================
  // SUITE 2: Absence of Horizontal Page Scroll & Scrollbar Suppression
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 2: Absence of Horizontal Page Scroll ---${C.reset}`);

  const scrollMetrics = await evaluate(`(() => {
    const html = document.documentElement;
    const body = document.body;
    const app = document.getElementById('app');
    const viewsContainer = document.querySelector('.views-container');

    const htmlComputed = window.getComputedStyle(html);
    const bodyComputed = window.getComputedStyle(body);
    const appComputed = window.getComputedStyle(app);

    // Initial scroll positions
    const initial = {
      windowScrollX: window.scrollX,
      docScrollWidth: html.scrollWidth,
      bodyScrollWidth: body.scrollWidth,
      appScrollWidth: app.scrollWidth,
      viewsScrollWidth: viewsContainer.scrollWidth
    };

    // Attempt aggressive horizontal scrolls
    window.scrollTo(1000, 0);
    html.scrollLeft = 1000;
    body.scrollLeft = 1000;
    app.scrollLeft = 1000;
    viewsContainer.scrollLeft = 1000;

    const afterAttempt = {
      windowScrollX: window.scrollX,
      htmlScrollLeft: html.scrollLeft,
      bodyScrollLeft: body.scrollLeft,
      appScrollLeft: app.scrollLeft,
      viewsScrollLeft: viewsContainer.scrollLeft
    };

    return {
      css: {
        htmlOverflowX: htmlComputed.overflowX,
        bodyOverflowX: bodyComputed.overflowX,
        appOverflowX: appComputed.overflowX,
        scrollbarWidth: bodyComputed.scrollbarWidth
      },
      initial,
      afterAttempt
    };
  })()`);

  assert(scrollMetrics.css.htmlOverflowX === 'hidden', `html overflow-x is strictly hidden (observed: ${scrollMetrics.css.htmlOverflowX})`);
  assert(scrollMetrics.css.bodyOverflowX === 'hidden', `body overflow-x is strictly hidden (observed: ${scrollMetrics.css.bodyOverflowX})`);
  assert(scrollMetrics.css.appOverflowX === 'hidden', `#app overflow-x is strictly hidden (observed: ${scrollMetrics.css.appOverflowX})`);
  assert(scrollMetrics.css.scrollbarWidth === 'none', `CSS scrollbar-width is set to none (observed: ${scrollMetrics.css.scrollbarWidth})`);
  assert(scrollMetrics.initial.docScrollWidth === 1920, `document.documentElement scrollWidth equals exactly 1920px (observed: ${scrollMetrics.initial.docScrollWidth})`);
  assert(scrollMetrics.initial.bodyScrollWidth === 1920, `body scrollWidth equals exactly 1920px (observed: ${scrollMetrics.initial.bodyScrollWidth})`);
  assert(scrollMetrics.initial.appScrollWidth === 1920, `#app scrollWidth equals exactly 1920px (observed: ${scrollMetrics.initial.appScrollWidth})`);
  assert(scrollMetrics.initial.viewsScrollWidth === 1920, `.views-container scrollWidth equals exactly 1920px (observed: ${scrollMetrics.initial.viewsScrollWidth})`);

  assert(scrollMetrics.afterAttempt.windowScrollX === 0, `window.scrollX remains 0 after horizontal scroll attempt (observed: ${scrollMetrics.afterAttempt.windowScrollX})`);
  assert(scrollMetrics.afterAttempt.htmlScrollLeft === 0, `html.scrollLeft remains 0 after scroll attempt (observed: ${scrollMetrics.afterAttempt.htmlScrollLeft})`);
  assert(scrollMetrics.afterAttempt.bodyScrollLeft === 0, `body.scrollLeft remains 0 after scroll attempt (observed: ${scrollMetrics.afterAttempt.bodyScrollLeft})`);
  assert(scrollMetrics.afterAttempt.appScrollLeft === 0, `#app.scrollLeft remains 0 after scroll attempt (observed: ${scrollMetrics.afterAttempt.appScrollLeft})`);

  // Verify horizontal scroll containment for all 6 views
  console.log(`\n${C.yellow}  Testing horizontal scroll containment across all 6 views...${C.reset}`);
  const viewIds = ['home', 'movies', 'series', 'search', 'details', 'player'];
  for (const viewName of viewIds) {
    const viewScrollData = await evaluate(`(() => {
      // Switch view
      window.location.hash = '#${viewName}';
      document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
      const activeView = document.getElementById('view-${viewName}');
      if (activeView) activeView.classList.add('active');

      const scrollPane = activeView ? activeView.querySelector('.view-scroll-pane') : null;
      let scrollPaneScrollLeft = 0;
      if (scrollPane) {
        scrollPane.scrollLeft = 500;
        scrollPaneScrollLeft = scrollPane.scrollLeft;
      }

      return {
        viewScrollWidth: activeView ? activeView.scrollWidth : null,
        scrollPaneWidth: scrollPane ? scrollPane.offsetWidth : null,
        scrollPaneScrollWidth: scrollPane ? scrollPane.scrollWidth : null,
        scrollPaneScrollLeft,
        docScrollWidth: document.documentElement.scrollWidth,
        windowScrollX: window.scrollX
      };
    })()`);

    assert(viewScrollData.docScrollWidth === 1920, `View #${viewName}: docScrollWidth stays 1920px (observed: ${viewScrollData.docScrollWidth})`);
    assert(viewScrollData.windowScrollX === 0, `View #${viewName}: windowScrollX stays 0 (observed: ${viewScrollData.windowScrollX})`);
    assert(viewScrollData.viewScrollWidth === 1920, `View #${viewName}: view container scrollWidth stays 1920px (observed: ${viewScrollData.viewScrollWidth})`);
    if (viewScrollData.scrollPaneScrollWidth !== null) {
      assert(viewScrollData.scrollPaneScrollWidth <= 1920, `View #${viewName}: view-scroll-pane scrollWidth (${viewScrollData.scrollPaneScrollWidth}px) <= 1920px`);
      assert(viewScrollData.scrollPaneScrollLeft === 0, `View #${viewName}: view-scroll-pane prohibited horizontal scroll (scrollLeft: ${viewScrollData.scrollPaneScrollLeft})`);
    }
  }

  // =========================================================================
  // SUITE 3: 5% TV-Safe Padding Adherence (96px Horizontal, 54px Vertical)
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 3: 5% TV-Safe Padding Adherence (96px / 54px) ---${C.reset}`);

  const safeAreaTokens = await evaluate(`(() => {
    const s = window.getComputedStyle(document.documentElement);
    return {
      safeX: s.getPropertyValue('--tv-safe-x').trim(),
      safeY: s.getPropertyValue('--tv-safe-y').trim(),
      usableW: s.getPropertyValue('--tv-usable-width').trim(),
      usableH: s.getPropertyValue('--tv-usable-height').trim()
    };
  })()`);

  assert(safeAreaTokens.safeX === '96px', `Token --tv-safe-x is exactly 96px (5% of 1920) (observed: ${safeAreaTokens.safeX})`);
  assert(safeAreaTokens.safeY === '54px', `Token --tv-safe-y is exactly 54px (5% of 1080) (observed: ${safeAreaTokens.safeY})`);
  assert(safeAreaTokens.usableW === '1728px', `Token --tv-usable-width is 1728px (1920 - 192) (observed: ${safeAreaTokens.usableW})`);
  assert(safeAreaTokens.usableH === '972px', `Token --tv-usable-height is 972px (1080 - 108) (observed: ${safeAreaTokens.usableH})`);

  // Check Header safe padding
  const headerSafeArea = await evaluate(`(() => {
    const brand = document.querySelector('.brand-container');
    const navPill = document.querySelector('.nav-glass-pill');
    const header = document.querySelector('.app-header');
    const headerStyle = window.getComputedStyle(header);

    return {
      paddingLeft: headerStyle.paddingLeft,
      paddingRight: headerStyle.paddingRight,
      brandLeft: brand.getBoundingClientRect().left,
      navPillRight: navPill.getBoundingClientRect().right
    };
  })()`);

  assert(headerSafeArea.paddingLeft === '96px', `App header padding-left conforms to 96px safe margin (observed: ${headerSafeArea.paddingLeft})`);
  assert(headerSafeArea.paddingRight === '96px', `App header padding-right conforms to 96px safe margin (observed: ${headerSafeArea.paddingRight})`);
  assert(headerSafeArea.brandLeft >= 96, `Brand container left (${headerSafeArea.brandLeft}px) >= 96px TV safe boundary`);
  assert(headerSafeArea.navPillRight <= 1824 + 1, `Navigation pill right (${headerSafeArea.navPillRight}px) <= 1824px TV safe boundary`);

  // Check Home View safe padding
  const homeSafeData = await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-home').classList.add('active');

    const hero = document.querySelector('.hero-content');
    const shelves = Array.from(document.querySelectorAll('#view-home .content-shelf'));

    return {
      heroLeft: hero ? hero.getBoundingClientRect().left : null,
      shelves: shelves.map(s => {
        const title = s.querySelector('.shelf-title');
        const rail = s.querySelector('.shelf-rail');
        const firstCard = rail ? rail.children[0] : null;
        return {
          titleLeft: title ? title.getBoundingClientRect().left : null,
          railLeft: rail ? rail.getBoundingClientRect().left : null,
          firstCardLeft: firstCard ? firstCard.getBoundingClientRect().left : null
        };
      })
    };
  })()`);

  assert(homeSafeData.heroLeft >= 96, `Home Hero content left (${homeSafeData.heroLeft}px) >= 96px TV safe margin`);
  for (let i = 0; i < homeSafeData.shelves.length; i++) {
    const s = homeSafeData.shelves[i];
    assert(s.titleLeft >= 96, `Home Shelf ${i} title left (${s.titleLeft}px) >= 96px TV safe margin`);
    assert(s.firstCardLeft >= 96, `Home Shelf ${i} first card left (${s.firstCardLeft}px) >= 96px TV safe margin`);
  }

  // Check Movies & Series 6-Column Grid safe padding
  for (const hub of ['movies', 'series']) {
    const hubSafeData = await evaluate(`(() => {
      document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
      const hubView = document.getElementById('view-${hub}');
      hubView.classList.add('active');

      const filterBar = hubView.querySelector('.filter-bar');
      const firstPill = filterBar ? filterBar.querySelector('.filter-pill') : null;
      const grid = hubView.querySelector('.content-grid-6col');
      const cards = grid ? Array.from(grid.querySelectorAll('.card-poster')) : [];

      return {
        firstPillLeft: firstPill ? firstPill.getBoundingClientRect().left : null,
        gridLeft: grid ? grid.getBoundingClientRect().left : null,
        gridRight: grid ? grid.getBoundingClientRect().right : null,
        cardCount: cards.length,
        col1CardLeft: cards[0] ? cards[0].getBoundingClientRect().left : null,
        col6CardRight: cards[5] ? cards[5].getBoundingClientRect().right : null
      };
    })()`);

    assert(hubSafeData.firstPillLeft >= 96, `${hub} first filter pill left (${hubSafeData.firstPillLeft}px) >= 96px TV safe margin`);
    assert(hubSafeData.col1CardLeft >= 96, `${hub} grid column 1 card left (${hubSafeData.col1CardLeft}px) >= 96px TV safe margin`);
    assert(hubSafeData.col6CardRight <= 1824 + 1, `${hub} grid column 6 card right (${hubSafeData.col6CardRight}px) <= 1824px TV safe margin`);
  }

  // Check Search View safe padding
  const searchSafeData = await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-search').classList.add('active');

    const input = document.querySelector('.search-input-box');
    const keyboard = document.querySelector('.tv-keyboard-container');
    const grid = document.querySelector('#view-search .content-grid-6col');
    const cards = grid ? Array.from(grid.querySelectorAll('.card-poster')) : [];

    return {
      inputLeft: input ? input.getBoundingClientRect().left : null,
      inputRight: input ? input.getBoundingClientRect().right : null,
      keyboardLeft: keyboard ? keyboard.getBoundingClientRect().left : null,
      keyboardRight: keyboard ? keyboard.getBoundingClientRect().right : null,
      col1CardLeft: cards[0] ? cards[0].getBoundingClientRect().left : null,
      col6CardRight: cards[5] ? cards[5].getBoundingClientRect().right : null
    };
  })()`);

  assert(searchSafeData.inputLeft >= 96 && searchSafeData.inputRight <= 1824,
    `Search input box bounded within [96px, 1824px] (left: ${searchSafeData.inputLeft}px, right: ${searchSafeData.inputRight}px)`);
  assert(searchSafeData.keyboardLeft >= 96 && searchSafeData.keyboardRight <= 1824,
    `Virtual TV keyboard bounded within [96px, 1824px] (left: ${searchSafeData.keyboardLeft}px, right: ${searchSafeData.keyboardRight}px)`);
  assert(searchSafeData.col1CardLeft >= 96, `Search results col 1 left (${searchSafeData.col1CardLeft}px) >= 96px TV safe margin`);
  assert(searchSafeData.col6CardRight <= 1824 + 1, `Search results col 6 right (${searchSafeData.col6CardRight}px) <= 1824px TV safe margin`);

  // Check Details View safe padding
  const detailsSafeData = await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-details').classList.add('active');

    const hero = document.querySelector('.details-content');
    const castRail = document.querySelector('#view-details .cast-item');
    const seasonBar = document.querySelector('#view-details .season-selector-bar');
    const epCard = document.querySelector('#view-details .card-episode');

    return {
      heroLeft: hero ? hero.getBoundingClientRect().left : null,
      castLeft: castRail ? castRail.getBoundingClientRect().left : null,
      seasonLeft: seasonBar ? seasonBar.getBoundingClientRect().left : null,
      epCardLeft: epCard ? epCard.getBoundingClientRect().left : null
    };
  })()`);

  assert(detailsSafeData.heroLeft >= 96, `Details content left (${detailsSafeData.heroLeft}px) >= 96px TV safe margin`);
  assert(detailsSafeData.castLeft >= 96, `Details cast rail first item left (${detailsSafeData.castLeft}px) >= 96px TV safe margin`);
  assert(detailsSafeData.seasonLeft >= 96, `Details season selector left (${detailsSafeData.seasonLeft}px) >= 96px TV safe margin`);
  assert(detailsSafeData.epCardLeft >= 96, `Details first episode card left (${detailsSafeData.epCardLeft}px) >= 96px TV safe margin`);

  // Check Player View OSD TV safe padding (x and y)
  const playerSafeData = await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-player').classList.add('active');

    const osd = document.querySelector('.player-osd');
    const osdStyle = window.getComputedStyle(osd);
    const backBtn = document.querySelector('#player-back-btn');
    const topBar = document.querySelector('.osd-top-bar');
    const bottomBar = document.querySelector('.osd-bottom-bar');
    const progressTrack = document.querySelector('.osd-progress-track');

    return {
      paddingTop: osdStyle.paddingTop,
      paddingBottom: osdStyle.paddingBottom,
      paddingLeft: osdStyle.paddingLeft,
      paddingRight: osdStyle.paddingRight,
      backBtnLeft: backBtn ? backBtn.getBoundingClientRect().left : null,
      topBarTop: topBar ? topBar.getBoundingClientRect().top : null,
      bottomBarBottom: bottomBar ? bottomBar.getBoundingClientRect().bottom : null,
      progressLeft: progressTrack ? progressTrack.getBoundingClientRect().left : null,
      progressRight: progressTrack ? progressTrack.getBoundingClientRect().right : null
    };
  })()`);

  assert(playerSafeData.paddingLeft === '96px', `Player OSD padding-left conforms to 96px safe margin (observed: ${playerSafeData.paddingLeft})`);
  assert(playerSafeData.paddingRight === '96px', `Player OSD padding-right conforms to 96px safe margin (observed: ${playerSafeData.paddingRight})`);
  assert(playerSafeData.paddingTop === '54px', `Player OSD padding-top conforms to 54px vertical safe margin (observed: ${playerSafeData.paddingTop})`);
  assert(playerSafeData.paddingBottom === '54px', `Player OSD padding-bottom conforms to 54px vertical safe margin (observed: ${playerSafeData.paddingBottom})`);
  assert(playerSafeData.topBarTop >= 54, `Player OSD top bar top (${playerSafeData.topBarTop}px) >= 54px vertical safe margin`);
  assert(playerSafeData.bottomBarBottom <= 1026 + 1, `Player OSD bottom bar bottom (${playerSafeData.bottomBarBottom}px) <= 1026px (1080 - 54px) vertical safe margin`);
  assert(playerSafeData.progressLeft >= 96, `Player progress track left (${playerSafeData.progressLeft}px) >= 96px TV safe margin`);
  assert(playerSafeData.progressRight <= 1824 + 1, `Player progress track right (${playerSafeData.progressRight}px) <= 1824px TV safe margin`);

  // =========================================================================
  // SUITE 4: 2:3 Poster Card & 16:9 Episode Card Geometry Verification
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 4: 2:3 Card Aspect Ratio & Geometry ---${C.reset}`);

  // Switch to Home to measure cards
  await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-home').classList.add('active');
  })()`);

  const cardGeometry = await evaluate(`(() => {
    // 1. Poster Cards in Home view
    const posters = Array.from(document.querySelectorAll('#view-home .card-poster')).map(card => {
      const media = card.querySelector('.poster-media');
      const img = card.querySelector('.poster-img');
      const mediaRect = media.getBoundingClientRect();
      const cardRect = card.getBoundingClientRect();
      const imgStyle = window.getComputedStyle(img);

      return {
        cardWidth: cardRect.width,
        mediaWidth: mediaRect.width,
        mediaHeight: mediaRect.height,
        ratio: mediaRect.width / mediaRect.height,
        invRatio: mediaRect.height / mediaRect.width,
        objectFit: imgStyle.objectFit
      };
    });

    // 2. Poster Cards in Movies view
    document.getElementById('view-home').classList.remove('active');
    document.getElementById('view-movies').classList.add('active');
    const moviePosters = Array.from(document.querySelectorAll('#view-movies .card-poster')).map(card => {
      const media = card.querySelector('.poster-media');
      const mediaRect = media.getBoundingClientRect();
      return {
        mediaWidth: mediaRect.width,
        mediaHeight: mediaRect.height,
        ratio: mediaRect.width / mediaRect.height
      };
    });

    // 3. Episode Cards in Details view
    document.getElementById('view-movies').classList.remove('active');
    document.getElementById('view-details').classList.add('active');
    const episodes = Array.from(document.querySelectorAll('#view-details .card-episode')).map(card => {
      const media = card.querySelector('.episode-media');
      const img = card.querySelector('.episode-img');
      const mediaRect = media.getBoundingClientRect();
      const imgStyle = window.getComputedStyle(img);

      return {
        mediaWidth: mediaRect.width,
        mediaHeight: mediaRect.height,
        ratio: mediaRect.width / mediaRect.height,
        objectFit: imgStyle.objectFit
      };
    });

    // 4. Provider square cards
    document.getElementById('view-details').classList.remove('active');
    document.getElementById('view-home').classList.add('active');
    const providers = Array.from(document.querySelectorAll('#view-home .card-provider')).map(card => {
      const box = card.querySelector('.provider-icon-box');
      const boxRect = box.getBoundingClientRect();
      return {
        width: boxRect.width,
        height: boxRect.height,
        ratio: boxRect.width / boxRect.height
      };
    });

    return { posters, moviePosters, episodes, providers };
  })()`);

  console.log(`  Evaluating ${cardGeometry.posters.length} poster cards in Home view...`);
  assert(cardGeometry.posters.length >= 12, `At least 12 poster cards present in Home shelves (found: ${cardGeometry.posters.length})`);

  let posterAspectErrors = 0;
  for (let i = 0; i < cardGeometry.posters.length; i++) {
    const p = cardGeometry.posters[i];
    const diff = Math.abs(p.ratio - (2 / 3));
    if (diff > 0.001 || p.mediaWidth !== 220 || p.mediaHeight !== 330) {
      posterAspectErrors++;
    }
  }
  assert(posterAspectErrors === 0, `All ${cardGeometry.posters.length} Home poster cards strictly conform to 220x330 (2:3 aspect ratio, ratio=0.6667)`);

  console.log(`  Evaluating ${cardGeometry.moviePosters.length} poster cards in 6-column Grid view...`);
  let gridAspectErrors = 0;
  for (let i = 0; i < cardGeometry.moviePosters.length; i++) {
    const p = cardGeometry.moviePosters[i];
    const diff = Math.abs(p.ratio - (2 / 3));
    if (diff > 0.001 || p.mediaWidth !== 220 || p.mediaHeight !== 330) {
      gridAspectErrors++;
    }
  }
  assert(gridAspectErrors === 0, `All ${cardGeometry.moviePosters.length} Grid poster cards strictly preserve 220x330 (2:3 aspect ratio)`);

  console.log(`  Evaluating ${cardGeometry.episodes.length} episode cards in Details view...`);
  assert(cardGeometry.episodes.length === 4, `Found 4 episode still cards in Details view`);
  let episodeAspectErrors = 0;
  for (let i = 0; i < cardGeometry.episodes.length; i++) {
    const ep = cardGeometry.episodes[i];
    const diff = Math.abs(ep.ratio - (16 / 9));
    if (diff > 0.002 || ep.mediaWidth !== 320 || ep.mediaHeight !== 180) {
      episodeAspectErrors++;
    }
  }
  assert(episodeAspectErrors === 0, `All ${cardGeometry.episodes.length} Episode still cards strictly conform to 320x180 (16:9 aspect ratio, ratio=1.7778)`);

  for (const p of cardGeometry.posters) {
    if (p.objectFit !== 'cover') posterAspectErrors++;
  }
  assert(posterAspectErrors === 0, `Poster images enforce object-fit: cover to prevent aspect ratio distortion`);

  for (const ep of cardGeometry.episodes) {
    if (ep.objectFit !== 'cover') episodeAspectErrors++;
  }
  assert(episodeAspectErrors === 0, `Episode still images enforce object-fit: cover to prevent aspect ratio distortion`);

  // Provider square tiles
  assert(cardGeometry.providers.length === 6, `Found 6 provider tiles in Browse by Provider shelf`);
  let providerErrors = 0;
  for (const pr of cardGeometry.providers) {
    if (pr.width !== 72 || pr.height !== 72 || pr.ratio !== 1.0) providerErrors++;
  }
  assert(providerErrors === 0, `Provider icon boxes enforce exact 1:1 square geometry (72px x 72px)`);

  // =========================================================================
  // SUITE 5: Spatial Remote Focus Stress & Boundary Expansion
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 5: Focus State Scaling & Boundary Expansion Stress ---${C.reset}`);

  const focusStressData = await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-movies').classList.add('active');

    const grid = document.querySelector('#view-movies .content-grid-6col');
    const cards = Array.from(grid.querySelectorAll('.card-poster'));
    const col1Card = cards[0];
    const col6Card = cards[5];

    // Focus col 1 card with transition override for deterministic instant measurement
    col1Card.style.setProperty('transition', 'none', 'important');
    col1Card.classList.add('focused');
    const r1 = col1Card.getBoundingClientRect();
    const col1FocusedRect = { left: r1.left, right: r1.right, width: r1.width, height: r1.height };
    const docScrollWidthCol1 = document.documentElement.scrollWidth;
    const bodyScrollWidthCol1 = document.body.scrollWidth;
    col1Card.classList.remove('focused');
    col1Card.style.removeProperty('transition');

    // Focus col 6 card
    col6Card.style.setProperty('transition', 'none', 'important');
    col6Card.classList.add('focused');
    const r6 = col6Card.getBoundingClientRect();
    const col6FocusedRect = { left: r6.left, right: r6.right, width: r6.width, height: r6.height };
    const docScrollWidthCol6 = document.documentElement.scrollWidth;
    const bodyScrollWidthCol6 = document.body.scrollWidth;
    col6Card.classList.remove('focused');
    col6Card.style.removeProperty('transition');

    // Focus first shelf card in Home
    document.getElementById('view-movies').classList.remove('active');
    document.getElementById('view-home').classList.add('active');
    const firstShelfCard = document.querySelector('#view-home .card-poster');
    firstShelfCard.style.setProperty('transition', 'none', 'important');
    firstShelfCard.classList.add('focused');
    const rShelf = firstShelfCard.getBoundingClientRect();
    const shelfCardFocusedRect = { left: rShelf.left, right: rShelf.right, width: rShelf.width, height: rShelf.height };
    const docScrollWidthShelf = document.documentElement.scrollWidth;
    firstShelfCard.classList.remove('focused');
    firstShelfCard.style.removeProperty('transition');

    return {
      col1: {
        rect: col1FocusedRect,
        docScrollWidth: docScrollWidthCol1,
        bodyScrollWidth: bodyScrollWidthCol1
      },
      col6: {
        rect: col6FocusedRect,
        docScrollWidth: docScrollWidthCol6,
        bodyScrollWidth: bodyScrollWidthCol6
      },
      shelf: {
        rect: shelfCardFocusedRect,
        docScrollWidth: docScrollWidthShelf
      }
    };
  })()`);

  assert(focusStressData.col1.docScrollWidth === 1920,
    `Focusing left edge card preserves document.scrollWidth === 1920px (observed: ${focusStressData.col1.docScrollWidth})`);
  assert(focusStressData.col1.bodyScrollWidth === 1920,
    `Focusing left edge card preserves body.scrollWidth === 1920px (observed: ${focusStressData.col1.bodyScrollWidth})`);
  assert(focusStressData.col1.rect.left >= 0,
    `Focusing left edge card (scale 1.08) does not clip past screen boundary left (observed: ${focusStressData.col1.rect.left}px >= 0)`);
  assert(focusStressData.col1.rect.left >= 48,
    `Focusing left edge card respects SMPTE 5% action safe margin (observed: ${focusStressData.col1.rect.left}px >= 48px)`);

  assert(focusStressData.col6.docScrollWidth === 1920,
    `Focusing right edge card preserves document.scrollWidth === 1920px (observed: ${focusStressData.col6.docScrollWidth})`);
  assert(focusStressData.col6.bodyScrollWidth === 1920,
    `Focusing right edge card preserves body.scrollWidth === 1920px (observed: ${focusStressData.col6.bodyScrollWidth})`);
  assert(focusStressData.col6.rect.right <= 1920,
    `Focusing right edge card (scale 1.08) does not bleed past 1920px screen edge (observed: ${focusStressData.col6.rect.right}px <= 1920)`);
  assert(focusStressData.col6.rect.right <= 1824,
    `Focusing right edge card remains within right safe area (observed: ${focusStressData.col6.rect.right}px <= 1824px)`);

  assert(focusStressData.shelf.docScrollWidth === 1920,
    `Focusing shelf card preserves document.scrollWidth === 1920px (observed: ${focusStressData.shelf.docScrollWidth})`);

  // =========================================================================
  // SUITE 6: Stress & Extreme Payload Resilience
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 6: Extreme Payload & Dynamic Injection Stress ---${C.reset}`);

  // Stress 1: Inject a 50-card shelf into Home view
  console.log(`  Injecting 50-card stress shelf into Home view...`);
  const largeShelfResult = await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-home').classList.add('active');

    const scrollPane = document.querySelector('#view-home .view-scroll-pane');
    const stressShelf = document.createElement('section');
    stressShelf.className = 'content-shelf';
    stressShelf.id = 'adversarial-stress-shelf';
    stressShelf.innerHTML = '<div class=\"shelf-header\"><h2 class=\"shelf-title\">Stress Shelf (50 Items)</h2></div><div class=\"shelf-rail\"></div>';

    const rail = stressShelf.querySelector('.shelf-rail');
    for (let i = 0; i < 50; i++) {
      const card = document.createElement('div');
      card.className = 'card-poster';
      card.setAttribute('data-nav', 'true');
      card.innerHTML = '<div class=\"poster-media\"><img class=\"poster-img\" src=\"https://image.tmdb.org/t/p/w500/1pdfLvkbY9ohJlCjQH2CZjjYVvJ.jpg\"><div class=\"poster-rating-badge\">★ 8.5</div></div><div class=\"poster-info\"><h3 class=\"poster-title\">Stress Item ' + i + '</h3><div class=\"poster-meta\"><span>2024</span></div></div>';
      rail.appendChild(card);
    }
    scrollPane.appendChild(stressShelf);

    const docScrollWidth = document.documentElement.scrollWidth;
    const bodyScrollWidth = document.body.scrollWidth;
    const windowScrollX = window.scrollX;
    const railScrollWidth = rail.scrollWidth;
    const railClientWidth = rail.clientWidth;

    // Cleanup stress shelf
    stressShelf.remove();

    return {
      docScrollWidth,
      bodyScrollWidth,
      windowScrollX,
      railScrollWidth,
      railClientWidth
    };
  })()`);

  assert(largeShelfResult.docScrollWidth === 1920,
    `Injecting 50-card shelf preserves document.scrollWidth === 1920px (observed: ${largeShelfResult.docScrollWidth})`);
  assert(largeShelfResult.bodyScrollWidth === 1920,
    `Injecting 50-card shelf preserves body.scrollWidth === 1920px (observed: ${largeShelfResult.bodyScrollWidth})`);
  assert(largeShelfResult.windowScrollX === 0,
    `Injecting 50-card shelf does not trigger horizontal window scroll (observed: ${largeShelfResult.windowScrollX})`);
  assert(largeShelfResult.railScrollWidth > largeShelfResult.railClientWidth,
    `Shelf rail internally handles overflow (scrollWidth: ${largeShelfResult.railScrollWidth}px > clientWidth: ${largeShelfResult.railClientWidth}px)`);

  // Stress 2: Extreme text overflow in card title
  console.log(`  Injecting 1000-character title into poster card...`);
  const textOverflowResult = await evaluate(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-home').classList.add('active');

    const card = document.querySelector('#view-home .card-poster');
    card.style.setProperty('transition', 'none', 'important');
    card.classList.remove('focused');

    const titleEl = card.querySelector('.poster-title');
    const originalText = titleEl.textContent;

    titleEl.textContent = 'A'.repeat(1000);
    const cardRect = card.getBoundingClientRect();
    const mediaRect = card.querySelector('.poster-media').getBoundingClientRect();
    const titleStyle = window.getComputedStyle(titleEl);

    // Restore original text
    titleEl.textContent = originalText;
    card.style.removeProperty('transition');

    return {
      cardWidth: cardRect.width,
      mediaWidth: mediaRect.width,
      textOverflow: titleStyle.textOverflow,
      whiteSpace: titleStyle.whiteSpace
    };
  })()`);

  assert(textOverflowResult.cardWidth === 220,
    `Card width remains strictly 220px under 1000-char title stress (observed: ${textOverflowResult.cardWidth}px)`);
  assert(textOverflowResult.textOverflow === 'ellipsis',
    `Title enforces text-overflow: ellipsis (observed: ${textOverflowResult.textOverflow})`);
  assert(textOverflowResult.whiteSpace === 'nowrap',
    `Title enforces white-space: nowrap (observed: ${textOverflowResult.whiteSpace})`);

  // Close CDP & Chrome
  ws.close();
  cleanup();

  // Print summary
  console.log(`\n${C.bold}${C.cyan}===============================================================${C.reset}`);
  console.log(`${C.bold}Test Execution Summary:${C.reset}`);
  console.log(`  Total Adversarial Checks:  ${totalTests}`);
  console.log(`  ${C.green}Passed Checks:             ${passedTests}${C.reset}`);
  console.log(`  ${failedTests === 0 ? C.green : C.red}Failed Checks:             ${failedTests}${C.reset}`);
  console.log(`${C.bold}${C.cyan}===============================================================${C.reset}\n`);

  if (failedTests > 0) {
    console.log(`${C.red}${C.bold}VERDICT: REQUEST_CHANGES (${failedTests} test failures detected)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`${C.green}${C.bold}VERDICT: APPROVE (100% of adversarial boundary tests passed)${C.reset}\n`);
    process.exit(0);
  }
}

runAdversarialLayoutTests().catch((err) => {
  console.error(`${C.red}Fatal harness error:${C.reset}`, err);
  process.exit(1);
});

