const { spawn } = require('child_process');
const http = require('http');

async function check() {
  const chrome = spawn('google-chrome-stable', [
    '--headless=new',
    '--remote-debugging-port=9343',
    '--user-data-dir=/tmp/chrome-test-prof-9',
    '--no-sandbox',
    '--disable-gpu',
    '--window-size=1920,1080',
    'file:///home/prem/webos-projects/cinejoy-webos/app/index.html'
  ]);

  await new Promise(r => setTimeout(r, 1200));

  const listRes = await new Promise((resolve, reject) => {
    http.get('http://127.0.0.1:9343/json/list', (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(JSON.parse(data)));
    }).on('error', reject);
  });

  const page = listRes.find(t => t.url.includes('cinejoy-webos'));
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);

  let msgId = 1;
  function send(method, params = {}) {
    return new Promise((resolve) => {
      const id = msgId++;
      const handler = (event) => {
        const data = JSON.parse(event.data);
        if (data.id === id) {
          ws.removeEventListener('message', handler);
          resolve(data.result);
        }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  await send('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false
  });

  const res = await send('Runtime.evaluate', {
    expression: \`(() => {
      document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
      const seriesView = document.getElementById('view-series');
      seriesView.classList.add('active');

      const filterBar = seriesView.querySelector('.filter-bar');
      const firstPill = filterBar.querySelector('.filter-pill');
