await evaluate(`(() => {
  const style = document.createElement('style');
  style.id = 'adversarial-no-transition';
  style.textContent = '.view { transition: none !important; }';
  document.head.appendChild(style);
})()`);

// =========================================================================
// SUITE 1: 1920x1080 Canvas Lock & Container Bounding Verification
// =========================================================================
console.log(`${C.bold}${C.magenta}--- Suite 1: 1920x1080 Canvas Lock & Dimensions ---${C.reset}`);

const canvasMetrics = await evaluate(`(() => {
  const html = document.documentElement;
  const body = document.body;
  const app = document.getElementById('app');
  const viewsContainer = document.querySelector('.views-container');
  const allViews = Array.from(document.querySelectorAll('.view')).map(v => {
    const s = window.getComputedStyle(v);
    return {
      id: v.id,
      cssWidth: s.width,
      cssHeight: s.height
    };
  });

  const computedHtml = window.getComputedStyle(html);
  const computedBody = window.getComputedStyle(body);
  const computedApp = window.getComputedStyle(app);

  return {
    window: { width: window.innerWidth, height: window.innerHeight },
    html: {
      width: computedHtml.width,
      height: computedHtml.height,
      minWidth: computedHtml.minWidth,
      minHeight: computedHtml.minHeight,
      maxWidth: computedHtml.maxWidth,
      maxHeight: computedHtml.maxHeight,
      overflow: computedHtml.overflow
    },
    body: {
      width: computedBody.width,
      height: computedBody.height,
      minWidth: computedBody.minWidth,
      minHeight: computedBody.minHeight,
      maxWidth: computedBody.maxWidth,
      maxHeight: computedBody.maxHeight,
      overflow: computedBody.overflow,
      offsetWidth: body.offsetWidth,
      offsetHeight: body.offsetHeight
    },
    app: {
      width: computedApp.width,
      height: computedApp.height,
      offsetWidth: app.offsetWidth,
      offsetHeight: app.offsetHeight
    },
    viewsContainer: {
      width: viewsContainer.offsetWidth,
      height: viewsContainer.offsetHeight
    },
    views: allViews
  };
})()`);

